width = 10;

with Carrier as c1:{
  in Leftward direction:{
    tuck Front_Needles[1:width:2];
  }
  in reverse direction:{
    tuck Front_Needles[0:width:2];
  }

  releasehook;
  for _ in range(10):{
    in reverse direction:{
      knit Loops;
    }
  }
}
cut c1;

